import{_ as a,o as e,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"初始面板","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/startup-panel.md","filePath":"zh-CN/user-guide/settings/startup-panel.md","lastUpdated":1783494793000}'),o={name:"zh-CN/user-guide/settings/startup-panel.md"};function n(l,t,i,d,h,u){return e(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="初始面板" tabindex="-1">初始面板 <a class="header-anchor" href="#初始面板" aria-label="Permalink to &quot;初始面板&quot;">​</a></h1><p>搜索框为空时，快速窗口结果列表上方显示的一个标签栏，不用输入查询就能快速访问最近文件、收藏夹和历史记录。</p><ul><li><strong>启用初始面板</strong> —— 总开关;关闭后，不管下面各个标签自己的设置如何，整个面板都不会激活。</li></ul><p>三个子标签:<strong>最近文件</strong>、<strong>上次目录</strong> 和 <strong>插件标签</strong>。</p><h2 id="最近文件" tabindex="-1">最近文件 <a class="header-anchor" href="#最近文件" aria-label="Permalink to &quot;最近文件&quot;">​</a></h2><ul><li><strong>启用面板</strong> —— 勾选框;搜索框为空时显示该标签。</li><li><strong>目录</strong> —— 要监控的文件夹，每行一个(添加/编辑/删除单行，以及批量文本编辑，和 <a href="./index-drives.html#排除规则">排除规则列表</a>是同一套交互)。可以是本地驱动器、已挂载的网络驱动器， 以及 WSL 路径(<code>\\\\wsl$\\...</code> 或 <code>\\\\wsl.localhost\\...</code>)——会匹配到你已经在 <a href="./index-drives.html">索引</a>里配置并建过索引的对应条目。</li><li><strong>显示的文件数量上限</strong> —— 范围 1–100，默认 10。</li><li><strong>时间范围(分钟)</strong> —— 只有在这个时间范围内修改过的文件才符合条件，叠加在上面的数量上限之上。 范围 1–43200(30 天)，默认 60。</li></ul><h2 id="上次目录" tabindex="-1">上次目录 <a class="header-anchor" href="#上次目录" aria-label="Permalink to &quot;上次目录&quot;">​</a></h2><ul><li><strong>启用面板</strong> —— 勾选框，默认开启。</li></ul><p>显示 SwiftList 接管系统文件打开/保存对话框时，最后停留过的目录内容——不用记路径，就能快速回到 刚才用文件选择器浏览过的地方。真正的索引会用到的隐藏/系统文件过滤和 <a href="./index-drives.html#排除规则">排除规则</a>在这里同样生效，所以不会出现 <code>$RECYCLE.BIN</code> 这类东西。本次 运行还没有触发过、该目录已经不存在、或者就是桌面(经常只是默认落脚点，不算真的&quot;去过&quot;)时，这 个标签完全不会出现。</p><h2 id="插件标签" tabindex="-1">插件标签 <a class="header-anchor" href="#插件标签" aria-label="Permalink to &quot;插件标签&quot;">​</a></h2><p>插件提供的标签(如历史记录、收藏夹)在面板里各自带一个 <strong>×</strong> 按钮，可以先把它隐藏起来。这只是 面板本地的&quot;先不显示&quot;选择——和在<a href="./plugins.html">插件</a>页面里把该插件组件本身禁用是两回事，后者是让 它彻底不参与使用。通过 × 关闭的标签会按提供它的插件分组显示在这里，未勾选;勾上即可重新打开。</p><p>只有插件层面已启用的标签才会出现在这个列表里——在<a href="./plugins.html">插件</a>页面整体禁用的组件，从一开 始就不会成为候选标签。</p>',12)])])}const c=a(o,[["render",n]]);export{g as __pageData,c as default};
